UIRankIconSparkleImage=function(game){Phaser.Image.call(this,game,0,0,'ranks','sparkle');this.anchor.setTo(0.5,0.5);this.tint=0xffff00+Math.random()*0x000099;this.kill();};UIRankIconSparkleImage.prototype=Object.create(Phaser.Image.prototype);UIRankIconSparkleImage.prototype.constructor=UIRankIconSparkleImage;UIRankIconSparkleImage.prototype.update=function(){if(!this.exists){return;}};UIRankIconSparkleImage.prototype.spawn=function(x,y,delay){this.reset(x,y);this.scale.setTo(0.01,0.01);this.sizeTween=this.game.add.tween(this.scale);this.sizeTween.to({x:1.0,y:1.0},UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,false,delay);this.sizeTween.to({x:0.01,y:0.01},UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,true);this.sizeTween.onComplete.add(function(){this.kill();},this);this.rotation=Math.random()*Math.PI;this.rotationTween=this.game.add.tween(this).to({rotation:this.rotation+Math.PI},2*UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,true,delay);};UIRankIconSparkleImage.prototype.remove=function(){if(this.sizeTween){this.sizeTween.stop();}if(this.rotationTween){this.rotationTween.stop();}this.kill();};UIRankIconSparkleImage.prototype.retire=function(){if(this.sizeTween){this.sizeTween.stop();}if(this.rotationTween){this.rotationTween.stop();}this.kill();};